script:
(function () {
  'use strict';
  // Hourly paycheck for tax year 2026. Hours are entered per week; a check covers 52 / periods weeks.
  //   Weekly gross   = rate x regular hours + rate x overtime multiplier x overtime hours
  //   (regular hours above 40 a week are moved to overtime, as the FLSA requires)
  //   Annual gross   = weekly gross x 52; per check = annual / pay periods
  //   Overtime deduction (IRC 225, 2025-2028): the FLSA premium (at most the "half" of
  //   time-and-a-half) up to $12,500 ($25,000 joint), less $100 per full $1,000 of MAGI over
  //   $150,000 ($300,000 joint); not available to married filing separately. It reduces federal
  //   taxable income only (FICA and the flat state rate still apply).
  //   Then federal tax, FICA, flat state tax and deductions as in the take-home paycheck model.
  // Verified (Node, scratch tests): $25/h, 40 + 5 OT hours, 1.5x, biweekly, single, 4% state:
  // gross $61,750 ($2,375.00/check); OT premium $3,250 deducted; taxable $42,400, tax $4,840;
  // SS $3,828.50, Medicare $895.38, state $2,470 -> $1,912.16/check ($1,897.16 without the
  // OT deduction). OT deduction cap $12,500 at $50/h + 10 OT; $11,700 at $50/h + 14 OT
  // (MAGI $158,600 -> 8 x $100 reduction); zero at $80/h + 20 OT; zero for MFS.
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Copied from take-home-paycheck-calculator (verified there). Brackets and standard
  // deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21). Child tax credit $2,200 and
  // $500 other-dependent credit: IRC 24(h) as amended by P.L. 119-21. Social Security wage base
  // and rates: SSA 2026 fact sheet. Medicare and 0.9% Additional Medicare: IRC 3101(b).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var CHILD_CREDIT = 2200;               // per child under 17
  var OTHER_DEPENDENT_CREDIT = 500;
  var CREDIT_PHASEOUT_START = { single: 200000, hoh: 200000, mfs: 200000, mfj: 400000 }; // $50 per $1,000
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500;
  var MEDICARE_RATE = 0.0145, ADDL_MEDICARE_RATE = 0.009, ADDL_MEDICARE_WITHHOLD_START = 200000;
  // Qualified overtime deduction: IRC 225 (P.L. 119-21); amounts from IRS Schedule 1-A Part III
  // (line 19: excess MAGI / $1,000 rounded down) and the IRS overtime-deduction Q&A.
  var OT_DEDUCTION_MAX = { single: 12500, hoh: 12500, mfj: 25000, mfs: 0 };
  var OT_PHASEOUT_START = { single: 150000, hoh: 150000, mfj: 300000, mfs: 0 };
  var FLSA_PREMIUM = 0.5;                // only the premium the FLSA requires qualifies
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2, minimumFractionDigits: 2 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1 });
  var hrs = new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 });

  function num(id) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }

  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0, marginal = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) {
        tax += (Math.min(taxable, upper) - lower) * RATES[i];
        marginal = RATES[i];
      }
      lower = upper;
    }
    return { tax: tax, marginal: marginal };
  }

  // Annual federal income tax: AGI - standard deduction - extra deductions, brackets, then
  // non-refundable child / dependent credits (refundable part of the child credit not modelled).
  function federalTax(agi, status, kids, otherDeps, extraDeduction) {
    var taxable = Math.max(0, agi - STANDARD_DEDUCTION[status] - (extraDeduction || 0));
    var bt = bracketTax(taxable, BRACKETS[status]);
    var credits = kids * CHILD_CREDIT + otherDeps * OTHER_DEPENDENT_CREDIT;
    var over = Math.max(0, agi - CREDIT_PHASEOUT_START[status]);
    credits = Math.max(0, credits - Math.ceil(over / 1000) * 50);
    return { taxable: taxable, tax: Math.max(0, bt.tax - credits), marginal: bt.marginal };
  }

  function ficaTax(wages) {
    var ss = SS_RATE * Math.min(wages, SS_WAGE_BASE);
    var medicare = MEDICARE_RATE * wages + ADDL_MEDICARE_RATE * Math.max(0, wages - ADDL_MEDICARE_WITHHOLD_START);
    return { ss: ss, medicare: medicare };
  }

  function overtimeDeduction(premium, magi, status) {
    if (status === 'mfs' || premium <= 0) return 0;
    var allowed = Math.min(premium, OT_DEDUCTION_MAX[status]);
    var reduction = Math.floor(Math.max(0, magi - OT_PHASEOUT_START[status]) / 1000) * 100;
    return Math.max(0, allowed - reduction);
  }

  function compute(o) {
    var reg = Math.min(o.regHours, 40);
    var ot = o.otHours + Math.max(0, o.regHours - 40);
    var regPay = o.rate * reg * 52, otPay = o.rate * o.mult * ot * 52;
    var gross = regPay + otPay;
    var premium = o.rate * Math.min(Math.max(0, o.mult - 1), FLSA_PREMIUM) * ot * 52;
    var k401 = gross * o.k401Pct / 100;
    var pretax = Math.min(o.pretaxPer * o.periods, Math.max(0, gross - k401));
    var fedWages = Math.max(0, gross - k401 - pretax);
    var otDed = o.useOtDed ? overtimeDeduction(premium, fedWages, o.status) : 0;
    var fed = federalTax(fedWages, o.status, o.kids, o.otherDeps, otDed);
    var f = ficaTax(Math.max(0, gross - pretax));
    var state = o.stateRate / 100 * fedWages;
    var post = o.postPer * o.periods;
    var net = gross - k401 - pretax - fed.tax - f.ss - f.medicare - state - post;
    return { reg: reg, ot: ot, moved: Math.max(0, o.regHours - 40), regPay: regPay, otPay: otPay,
             gross: gross, premium: premium, otDed: otDed, k401: k401, pretax: pretax, taxable: fed.taxable,
             federal: fed.tax, marginal: fed.marginal, ss: f.ss, medicare: f.medicare, state: state,
             post: post, net: net, taxes: fed.tax + f.ss + f.medicare + state };
  }

  function setText(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function update() {
    var o = {
      rate: num('hpRate'), regHours: num('hpReg'), otHours: num('hpOt'), mult: num('hpMult'),
      periods: parseInt(document.getElementById('hpFreq').value, 10),
      status: document.getElementById('hpStatus').value, k401Pct: num('hp401k'),
      pretaxPer: num('hpPretax'), kids: Math.round(num('hpKids')), otherDeps: Math.round(num('hpOtherDeps')),
      stateRate: num('hpState'), postPer: num('hpPosttax'),
      useOtDed: document.getElementById('hpOtDed').checked
    };
    if (!BRACKETS[o.status]) o.status = 'single';
    if (!(o.periods > 0)) o.periods = 26;
    var error = document.getElementById('hpError');
    var nums = [o.rate, o.regHours, o.otHours, o.mult, o.k401Pct, o.pretaxPer, o.kids, o.otherDeps, o.stateRate, o.postPer];
    var bad = nums.some(function (v) { return !isFinite(v) || v < 0; }) || o.rate > 1e5 ||
              o.regHours + o.otHours > 168 || o.mult < 1 || o.mult > 5 || o.k401Pct > 100 ||
              o.stateRate > 20 || o.kids > 20 || o.otherDeps > 20;
    var msg = 'Enter a non-negative hourly rate, no more than 168 hours a week in total, an overtime multiplier from 1 to 5, a 401(k) rate up to 100% and a state rate from 0 to 20%.';
    var r = null;
    if (!bad) {
      r = compute(o);
      if (r.k401 + o.pretaxPer * o.periods + r.post > r.gross + 1e-9) {
        bad = true;
        msg = 'Your deductions add up to more than your gross pay. Lower the 401(k) rate or the per-paycheck deductions.';
      }
    }
    error.hidden = !bad;
    if (bad) { error.textContent = msg; return; }

    var p = o.periods, weeks = 52 / p;
    setText('hpNet', money.format(r.net / p));
    setText('hpGross', money.format(r.gross / p));
    setText('hpTaxPer', money.format(r.taxes / p));
    setText('hpHours', hrs.format((r.reg + r.ot) * weeks) + ' (' + hrs.format(r.ot * weeks) + ' overtime)');
    setText('hpRegPay', money.format(r.regPay / p));
    setText('hpOtPay', money.format(r.otPay / p));
    var totalHours = (r.reg + r.ot) * 52;
    setText('hpNetHour', totalHours > 0 ? money.format(r.net / totalHours) : money.format(0));
    setText('hpOtDedOut', money.format(r.otDed));
    setText('hpMarginal', pct.format(r.marginal));

    var rows = [
      ['Regular pay', r.regPay],
      ['Overtime pay', r.otPay],
      ['Gross pay', r.gross],
      ['401(k) / 403(b) contribution', -r.k401],
      ['Other pre-tax deductions', -r.pretax],
      ['Federal income tax', -r.federal],
      ['Social Security (6.2%)', -r.ss],
      ['Medicare', -r.medicare],
      ['State and local income tax', -r.state],
      ['After-tax deductions', -r.post],
      ['Take-home pay', r.net]
    ];
    document.getElementById('hpBreakdown').innerHTML = rows.map(function (row, i) {
      var cell = function (v) { if (Math.abs(v) < 0.005) return money.format(0); return v < 0 ? '−' + money.format(-v) : money.format(v); };
      var strong = row[0] === 'Gross pay' || i === rows.length - 1;
      return '<tr><th scope="row">' + (strong ? '<strong>' + row[0] + '</strong>' : row[0]) + '</th><td>' +
             cell(row[1] / p) + '</td><td>' + cell(row[1]) + '</td></tr>';
    }).join('');

    var notes = [];
    if (r.moved > 0) notes.push('Regular hours above 40 a week count as overtime, so ' + hrs.format(r.moved) + ' of your regular hours were moved to overtime.');
    if (o.useOtDed && r.ot > 0 && o.status === 'mfs') notes.push('The overtime deduction is not available when married filing separately.');
    if (o.useOtDed && r.premium > 0 && o.status !== 'mfs') notes.push('Overtime deduction: ' + money.format(r.otDed) + ' of your ' + money.format(r.premium) +
      ' yearly overtime premium is deducted from federal taxable income (' + TAX_YEAR + ' rules). Your employer may not reduce withholding for it, so the saving can arrive as a refund.');
    if (o.kids + o.otherDeps > 0 && r.federal === 0) notes.push('Your credits cover all of your federal income tax, so federal tax is zero.');
    var noteEl = document.getElementById('hpNote');
    noteEl.hidden = notes.length === 0;
    noteEl.textContent = notes.join(' ');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('hpForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
